            var cw1im    = ws.cw1im;
            // Processed in Hermitian-symmetric pairs (k, M-k): one twiddle and one load of the
            // (k, M-k) spectrum serve both re-packed outputs. Under k -> M-k the conjugate twiddle
            // maps so E_im, a and Re(W) flip sign, giving O_re unchanged, O_im negated — hence
            // cz[M-k] = E_re + O_im, sz[M-k] = O_re - E_im.
            int half = M >> 1;
            for (int k = 1; k < half; k++)
            {
                int kr = M - k;
                double xr_k  = re[k],  xi_k  = im[k];
                double xr_kr = re[kr], xi_kr = im[kr];

                // E[k] = (X[k] + conj(X[M-k])) / 2
                double E_re = (xr_k + xr_kr) * (double)0.5;
                double E_im = (xi_k - xi_kr) * (double)0.5;

                // (X[k] - conj(X[M-k])) = a + i·b
                double a = xr_k - xr_kr;
                double b = xi_k + xi_kr;

                // conj(W_N^k): reconstruct W_N^k via WQ, then negate its imaginary part.
                // O[k] = (a + i·b) · conj(W_N^k) / 2  →  complex multiply (a+ib)·(cRe+icIm):
                //   real = a·cRe - b·cIm,  imag = b·cRe + a·cIm
                WQ(cqPtr, k, N, out double cRe, out double cImPos);
                double cIm = -cImPos;   // negate imaginary part for conjugate
                double O_re = (a * cRe - b * cIm) * (double)0.5;
                double O_im = (b * cRe + a * cIm) * (double)0.5;

                // Y[k] = E[k] + i·O[k], and its M-k partner.
                cz[k]  = E_re - O_im;   sz[k]  = E_im + O_re;
                cz[kr] = E_re + O_im;   sz[kr] = O_re - E_im;
            }
            // Middle bin k = M/2 (self-paired: M-k == k). Skipped for M == 1 (N == 2).
            if (M >= 2)
            {
                int k = half;
                int kr = M - k;
                double xr_k  = re[k],  xi_k  = im[k];
                double xr_kr = re[kr], xi_kr = im[kr];

                double E_re = (xr_k + xr_kr) * (double)0.5;
                double E_im = (xi_k - xi_kr) * (double)0.5;
                double a = xr_k - xr_kr;
                double b = xi_k + xi_kr;

                WQ(cqPtr, k, N, out double cRe, out double cImPos);
                double cIm = -cImPos;
                double O_re = (a * cRe - b * cIm) * (double)0.5;
                double O_im = (b * cRe + a * cIm) * (double)0.5;

                cz[k] = E_re - O_im;
                sz[k] = E_im + O_re;
            }

            // One M-point inverse FFT via radix-4 (with the shared quarter table, tableN = ws.n = N).
            var visitedScratch = ws.visited;
            if (IsPowerOf4(M))
                FftCoreRadix4(ref cz, ref sz, ref sw1re, ref sw1im, true);
            else
                FftCoreRadix4Mixed(ref cz, ref sz, ref sw1re, ref sw1im, ref cw1re, ref cw1im, visitedScratch, true);

            // Deinterleave: real[2j] = even[j], real[2j+1] = odd[j].
            for (int j = 0; j < M; j++)
            {
                real[2 * j]     = cz[j];
                real[2 * j + 1] = sz[j];
            }
        }

        // ---- radix-4 DIT FFT ----
        //
        // True radix-4 decimation-in-time for lengths that are exact powers of 4 (log4(n) even bits).
        // Radix-4 halves the number of full-array passes vs radix-2: log4(N) vs log2(N) stages,
        // trading twiddle-table memory against half the pass count.
        //
        // Inverse via conjugate trick: conjugate → forward radix-4 → conjugate + scale (1/N).
        // Permutation: base-4 digit reversal (reverse digit order in base-4 = swap bit-pairs).
        // Butterfly: forward DFT sign convention X[k] = Σ x[n]·exp(-2πi·kn/N).

        // IsPowerOf4 and ReverseBase4Digits live in OpHelpers.Shared.cs (type-agnostic, emitted once).

        // Inner radix-4 butterfly pointer kernel (wide + scalar hybrid).
        // Performs log4(n) stages of radix-4 DIT butterflies on already-permuted data.
        // s1r/s1i are the contiguous per-stage W^1 table (ws.sw1re/sw1im), laid out in stage order
        // (qq = 1, 4, 16, …); EVERY stage reads its precomputed W^1 from it and derives W^2/W^3
        // in-register — no runtime twiddle reconstruction. Stages with quarter-stride q >= doubleW.Width
        // vectorize across j (Width consecutive j give contiguous wide re/im loads and a contiguous
        // read of s1r/s1i); smaller stages run the identical scalar butterfly. stageOff walks the
        // table one stage at a time, so a size-M sub-transform reads the length-log4(M) prefix.
        // n is the DATA/transform size (a power of 4). All pointer arguments are non-aliasing.
        [MethodImpl(MethodImplOptions.NoInlining)]
        static unsafe void FftCoreRadix4Ptr(
            [NoAlias] double* re, [NoAlias] double* im,
            [NoAlias] double* s1r, [NoAlias] double* s1i, int n)
        {
            // q = quarter-size per group (stride); starts at 1 and quadruples each stage.
            int W = doubleW.Width;
            int stageOff = 0;   // running offset into the contiguous per-stage sw1 table

            for (int q = 1; q < n; q <<= 2)
            {
                int len = q << 2;       // 4q

                if (q >= W)
                {
                    // Wide stage: q (a power of 4, >= W) is a multiple of W, so no j tail.
                    for (int base_ = 0; base_ < n; base_ += len)
                    {
                        for (int j = 0; j < q; j += W)
                        {
                            int i0 = base_ + j, i1 = i0 + q, i2 = i1 + q, i3 = i2 + q;

                            doubleW Are = doubleW.Load(re + i0, 0), Aim = doubleW.Load(im + i0, 0);

                            // W^1 loaded; W^2 = W^1·W^1, W^3 = W^1·W^2 derived in-register.
                            doubleW w1r = doubleW.Load(s1r + stageOff + j, 0), w1i = doubleW.Load(s1i + stageOff + j, 0);
                            doubleW w2r = w1r * w1r - w1i * w1i, w2i = w1r * w1i + w1i * w1r;
                            doubleW w3r = w1r * w2r - w1i * w2i, w3i = w1r * w2i + w1i * w2r;

                            doubleW x1r = doubleW.Load(re + i1, 0), x1i = doubleW.Load(im + i1, 0);
                            doubleW Bre = w1r * x1r - w1i * x1i;
                            doubleW Bim = w1r * x1i + w1i * x1r;

                            doubleW x2r = doubleW.Load(re + i2, 0), x2i = doubleW.Load(im + i2, 0);
                            doubleW Cre = w2r * x2r - w2i * x2i;
                            doubleW Cim = w2r * x2i + w2i * x2r;

                            doubleW x3r = doubleW.Load(re + i3, 0), x3i = doubleW.Load(im + i3, 0);
                            doubleW Dre = w3r * x3r - w3i * x3i;
                            doubleW Dim = w3r * x3i + w3i * x3r;

                            doubleW T0re = Are + Cre, T0im = Aim + Cim;
                            doubleW T1re = Are - Cre, T1im = Aim - Cim;
                            doubleW T2re = Bre + Dre, T2im = Bim + Dim;
                            doubleW T3re = Bre - Dre, T3im = Bim - Dim;

                            doubleW.Store(re + i0, 0, T0re + T2re); doubleW.Store(im + i0, 0, T0im + T2im);
                            doubleW.Store(re + i2, 0, T0re - T2re); doubleW.Store(im + i2, 0, T0im - T2im);
                            doubleW.Store(re + i1, 0, T1re + T3im); doubleW.Store(im + i1, 0, T1im - T3re);
                            doubleW.Store(re + i3, 0, T1re - T3im); doubleW.Store(im + i3, 0, T1im + T3re);
                        }
                    }
                }
                else
                {
                    // Small stage (q < Width): identical butterfly, scalar. j-outer so the stage's
                    // q (<= 4) twiddle triples are read from sw1 and W^2/W^3 derived ONCE per j, held
                    // in registers across every group — no per-butterfly reconstruction.
                    for (int j = 0; j < q; j++)
                    {
                        double w1r = s1r[stageOff + j], w1i = s1i[stageOff + j];
                        double w2r = w1r * w1r - w1i * w1i, w2i = w1r * w1i + w1i * w1r;
                        double w3r = w1r * w2r - w1i * w2i, w3i = w1r * w2i + w1i * w2r;
                        for (int base_ = 0; base_ < n; base_ += len)
                        {
                            int i0 = base_ + j, i1 = i0 + q, i2 = i1 + q, i3 = i2 + q;

                            double A_re = re[i0], A_im = im[i0];
                            double B_re = w1r * re[i1] - w1i * im[i1];
                            double B_im = w1r * im[i1] + w1i * re[i1];
                            double C_re = w2r * re[i2] - w2i * im[i2];
                            double C_im = w2r * im[i2] + w2i * re[i2];
                            double D_re = w3r * re[i3] - w3i * im[i3];
                            double D_im = w3r * im[i3] + w3i * re[i3];

                            double T0_re = A_re + C_re, T0_im = A_im + C_im;
                            double T1_re = A_re - C_re, T1_im = A_im - C_im;
                            double T2_re = B_re + D_re, T2_im = B_im + D_im;
                            double T3_re = B_re - D_re, T3_im = B_im - D_im;

                            re[i0] = T0_re + T2_re; im[i0] = T0_im + T2_im;
                            re[i2] = T0_re - T2_re; im[i2] = T0_im - T2_im;
                            re[i1] = T1_re + T3_im; im[i1] = T1_im - T3_re;
                            re[i3] = T1_re - T3_im; im[i3] = T1_im + T3_re;
                        }
                    }
                }
                stageOff += q;
            }
        }

        // Outer radix-4 DIT core: permutation + conjugate trick + pointer kernel + inverse scale.
        // Transform size is re.N (must be a power of 4, caller guarantees).
        // sw1re/sw1im are the workspace's per-stage W^1 table; a size-M sub-transform reads its
        // length-log4(M) prefix (the entries are shared across all sub-transforms of one workspace).
        static unsafe void FftCoreRadix4(ref doubleN re, ref doubleN im,
                                         ref doubleN sw1re, ref doubleN sw1im,
                                         bool inverse)
        {
            int size = re.N;
            if (size == 1) return;

            // Conjugate trick (see section banner above).
            if (inverse)
                for (int i = 0; i < size; i++)
                    im[i] = -im[i];

            // Digit reversal + butterfly stages via shared slice helper.
            double* rePtr  = re.Data.Ptr;
            double* imPtr  = im.Data.Ptr;
            double* s1rPtr = sw1re.Data.Ptr;
            double* s1iPtr = sw1im.Data.Ptr;
            FftCoreRadix4Slice(rePtr, imPtr, s1rPtr, s1iPtr, size);

            if (inverse)
            {
                double invN = (double)1 / (double)size;
                for (int i = 0; i < size; i++)
                {
                    re[i] =  re[i] * invN;
                    im[i] = -im[i] * invN;   // undo conjugate, apply 1/N scale
                }
            }
        }

        // Shared helper: base-4 digit reversal + butterfly on a raw pointer slice of length `size`.
        // re/im are already offset to the start of the sub-array; s1r/s1i are the workspace's
        // per-stage W^1 table (shared across sub-transforms). size must be a power of 4.
        static unsafe void FftCoreRadix4Slice(
            double* re, double* im,
            double* s1r, double* s1i,
            int size)
        {
            if (size <= 1) return;

            // Base-4 digit reversal on this slice.
            int log4n = 0;
            for (int t = size; t > 1; t >>= 2) log4n++;

            for (int i = 0; i < size; i++)
            {
                int j = ReverseBase4Digits(i, log4n);
                if (j > i)
                {
                    double tr = re[i]; re[i] = re[j]; re[j] = tr;
                    double ti = im[i]; im[i] = im[j]; im[j] = ti;
                }
            }

            // Butterfly stages.
            FftCoreRadix4Ptr(re, im, s1r, s1i, size);
        }

        // Mixed-radix DIT for N = 2·4^k (IsPow2(N) && !IsPowerOf4(N)).
        // Transform size is re.N; tableN is the twiddle table length (>= re.N, multiple of re.N).
        // One radix-2 level wraps two size-M = re.N/2 radix-4 sub-FFTs; M is always a power of 4.
        // Inverse via conjugate trick at the OUTER level — sub-FFTs always run forward.
        //
        // In-place implementation — no doubleN Temp allocations.
        // Step 1: de-interleave in-place via cycle-following (bool visited scratch, N bytes).
        // Step 2: two radix-4 sub-FFTs on the contiguous even/odd halves via FftCoreRadix4Slice.
        // Step 3: radix-2 DIT combine, writing natural-order output back in-place.
        // Combine twiddle: W_size^k = T_tableN[k*(tableN/size)].
        // visited is a workspace scratch of length >= size (0/1 flags, double-typed).
        // The caller passes ws.visited (length n); only [0, size) is used, cleared at entry.
        static unsafe void FftCoreRadix4Mixed(ref doubleN re, ref doubleN im,
                                              ref doubleN sw1re, ref doubleN sw1im,
                                              ref doubleN cw1re, ref doubleN cw1im,
                                              doubleN visited,
                                              bool inverse)
        {
            int size = re.N;
            int M = size >> 1;   // size/2, always a power of 4

            // Conjugate trick at the outer level (see banner above).
            if (inverse)
                for (int i = 0; i < size; i++)
                    im[i] = -im[i];

            // Step 1: In-place de-interleave (unshuffle) via cycle-following.
            // dst(i) = i/2 if i is even; M + i/2 if i is odd.
            // After the permutation: [0,M) holds even-indexed elements, [M,2M) holds odd-indexed,
            // both in natural order — exactly what FftCoreRadix4Slice expects as input.
            // Cycle-following uses the workspace visited scratch (0 = unvisited, 1 = visited).
            // Clear [0, size) — workspace is reused across calls so it must be zeroed each time.
            for (int i = 0; i < size; i++)
                visited[i] = (double)0;

            for (int s = 0; s < size; s++)
            {
                if (visited[s] != (double)0) continue;
                visited[s] = (double)1;

                int j = (s & 1) == 0 ? (s >> 1) : (M + (s >> 1));
                if (j == s) continue;   // fixed point (s==0 or s==size-1)

                double carryRe = re[s], carryIm = im[s];
                while (j != s)
                {
                    double tmpRe = re[j], tmpIm = im[j];
                    re[j] = carryRe;
                    im[j] = carryIm;
                    visited[j] = (double)1;
                    carryRe = tmpRe;
                    carryIm = tmpIm;
                    j = (j & 1) == 0 ? (j >> 1) : (M + (j >> 1));
                }
                re[s] = carryRe;
                im[s] = carryIm;
            }

            // Step 2: Two in-place radix-4 sub-FFTs on the contiguous halves (no temp copy).
            // Each reads the length-log4(M) prefix of the shared per-stage W^1 table (sw1) — no
            // sub-table copies.
            double* rePtr  = re.Data.Ptr;
            double* imPtr  = im.Data.Ptr;
            double* s1rPtr = sw1re.Data.Ptr;
            double* s1iPtr = sw1im.Data.Ptr;

            FftCoreRadix4Slice(rePtr,     imPtr,     s1rPtr, s1iPtr, M);
            FftCoreRadix4Slice(rePtr + M, imPtr + M, s1rPtr, s1iPtr, M);

            // Step 3: Radix-2 DIT combine (wide + scalar hybrid).
            //   X[k]   = E[k] + W_size^k * O[k]
            //   X[k+M] = E[k] - W_size^k * O[k]
            // The combine twiddle W_size^k = T_tableN[k*(tableN/size)] is pre-gathered contiguously
            // into cw1r/cw1i (ws.cw1re/cw1im) so k indexes it directly: Width consecutive k give
            // contiguous wide loads of the twiddles AND the E/O data (re[k],im[k],re[M+k],im[M+k]).
            // The scalar tail handles the M < Width remainder (M is a power of 4, so no partial
            // wide iteration once M >= Width). Bit-identical to the scalar combine per element.
            double* cw1r = cw1re.Data.Ptr;
            double* cw1i = cw1im.Data.Ptr;
            int Wc = doubleW.Width;
            int k = 0;
            for (; k + Wc <= M; k += Wc)
            {
                doubleW wr = doubleW.Load(cw1r + k, 0), wi = doubleW.Load(cw1i + k, 0);
                doubleW er  = doubleW.Load(rePtr + k, 0),     ei  = doubleW.Load(imPtr + k, 0);
                doubleW or_ = doubleW.Load(rePtr + M + k, 0), oi_ = doubleW.Load(imPtr + M + k, 0);
                doubleW tr  = wr * or_ - wi * oi_;
                doubleW ti  = wr * oi_ + wi * or_;
                doubleW.Store(rePtr + k, 0,     er + tr); doubleW.Store(imPtr + k, 0,     ei + ti);
                doubleW.Store(rePtr + M + k, 0, er - tr); doubleW.Store(imPtr + M + k, 0, ei - ti);
            }
            for (; k < M; k++)
            {
                double wr = cw1r[k], wi = cw1i[k];
                double er  = rePtr[k],     ei  = imPtr[k];
                double or_ = rePtr[M + k], oi_ = imPtr[M + k];
                double tr  = wr * or_ - wi * oi_;
                double ti  = wr * oi_ + wi * or_;
                rePtr[k]     = er + tr; imPtr[k]     = ei + ti;
                rePtr[M + k] = er - tr; imPtr[M + k] = ei - ti;
            }

            if (inverse)
            {
                double invN = (double)1 / (double)size;
                for (int i = 0; i < size; i++)
                {
                    re[i] =  re[i] * invN;
                    im[i] = -im[i] * invN;   // undo conjugate, apply 1/N scale
                }
            }
        }

    }
}
